INSERT INTO posts (owner_id, owner_name, title, slug, summary, content, tags, cover_theme, status, created_at) VALUES
('lky-seed', '卢柯宇', '欢迎来到我的博客', 'welcome-to-my-blog', '这里记录我在吉林大学计算机系的学习、项目与思考。第一篇文章，说说这个博客为什么存在。', E'# 欢迎来到我的博客\n\n你好，我是卢柯宇，吉林大学计算机科学与技术 2024 级本科生。这个博客是我为自己搭建的一片自留地——用来记录课程项目、踩过的坑，以及一些不太成熟的思考。\n\n## 这个博客里有什么\n\n- **课程项目复盘**：从 C 语言的菜鸟驿站系统，到 PHP 的校园圈子，每个项目我都会写一篇完整的复盘\n- **学习笔记**：数据结构、Web 开发、设计方法，学到哪写到哪\n- **随笔**：一些关于成长、关于技术的碎碎念\n\n## 为什么自己搭一个\n\n> 学习计算机的人，需要有一颗强大的心。\n\n写在别人平台上的东西总像是寄人篱下。这个博客的前端是 React，文章数据存在云端数据库，图片走云端存储，登录后可以在线写作和发布——从写代码到写文字，整个链路都是自己的。\n\n## 接下来\n\n我会把大学里做过的五个项目逐一复盘。如果你有相似的经历，欢迎通过关于页面找到我，一起交流。', ARRAY['随笔','博客'], 'aurora', 'published', now() - interval '30 days'),
('lky-seed', '卢柯宇', '菜鸟驿站管理系统：我的第一个完整 C 语言项目', 'cainiao-station-c-project', '2024 年程序设计课程设计。用纯 C 语言实现管理员与顾客双角色的快递站管理系统，聊聊数据结构规划和文件持久化的取舍。', E'# 菜鸟驿站管理系统：我的第一个完整 C 语言项目\n\n这是 2024 年程序设计课程设计的作品，也是我第一个从零写到尾、真正“能跑起来用”的系统。\n\n## 要解决什么问题\n\n校园快递站的日常业务看起来简单：入库、取件、计费。但真正拆开来，**快递、用户、费用与库存状态彼此关联**，任何一个状态没对齐，数据就会打架。\n\n## 架构取舍\n\n我把系统拆成两条任务链：\n\n1. **管理员侧**：快件入库、库存查询、滞留预警、计费规则配置\n2. **顾客侧**：取件码验证、费用查询、历史记录\n\n数据层用结构体组织业务实体：\n\n```c\ntypedef struct {\n    char id[20];        // 快递单号\n    char phone[12];     // 收件人手机号\n    int shelf;          // 货架位置\n    double fee;         // 滞留费用\n    time_t inTime;      // 入库时间\n    int status;         // 0 在库 / 1 已取\n} Package;\n```\n\n持久化没有用数据库（课设要求纯 C），而是**文件 IO**：每次关键操作后落盘，启动时全量读入内存。这个方案简单直接，也让我第一次认真思考“什么时候该写盘、写挂了怎么办”。\n\n## 最收获的三件事\n\n- **先画状态图再写代码**：快件状态机理清了，分支 bug 少了一半\n- **计费模型参数化**：把免费时长、费率抽成配置，答辩时老师现场改规则也不怕\n- **预警做主动**：滞留件主动提醒，比等用户来查体验好太多\n\n完整源码在我的 GitHub 上，仓库名 Cainiao-Station。', ARRAY['C语言','课程设计','系统设计'], 'cobalt', 'published', now() - interval '24 days'),
('lky-seed', '卢柯宇', '五子棋对弈：数据结构课设里的搜索与剪枝', 'gomoku-match-chess-ai', '2025 年数据结构课程设计。用 C++ 写五子棋对弈程序，从棋盘表示到极大极小搜索，记录一次完整的算法实践。', E'# 五子棋对弈：数据结构课设里的搜索与剪枝\n\n2025 年数据结构课程设计，题目是五子棋对弈。表面是写个棋类游戏，实际上是一次**搜索算法与评估函数**的完整训练。\n\n## 棋盘怎么表示\n\n15×15 的棋盘用二维数组最直接，但判断连子时方向数组的写法决定了代码的优雅程度：\n\n```cpp\nconst int dx[4] = {1, 0, 1, 1};\nconst int dy[4] = {0, 1, 1, -1};\n// 四个方向：横、竖、主对角、副对角\n```\n\n一次遍历就能完成胜负判定，这是数据结构课上“用空间换清晰”的典型例子。\n\n## AI 的核心：估值 + 搜索\n\n电脑下棋分两步：\n\n1. **局面评估**：给每个空位打分。活四、冲四、活三……不同棋型不同权重，进攻分和防守分要同时算\n2. **搜索决策**：贪心只看一步容易被骗，用极大极小搜索看两层，再加上 Alpha-Beta 剪枝控制耗时\n\n调权重是最磨人的部分。防守权重低了，AI 会被活三直接带走；进攻权重低了，它又能赢不赢、急得你拍桌子。\n\n## 课设之外的体会\n\n> 好的评估函数不是算出来的，是输出来的。\n\n我大概跟自己的 AI 对弈了五十多盘，每输一盘就回去改一处权重。这种“用失败驱动迭代”的感觉，比课本上的伪代码真实得多。\n\n源码在 GitHub 的 Gomoku-match 仓库。', ARRAY['C++','数据结构','算法'], 'violet', 'published', now() - interval '18 days'),
('lky-seed', '卢柯宇', '校园圈子 Campus Circle：一次 PHP + MySQL 全栈实战', 'campus-circle-php-fullstack', '2024 级 Web 开发大作业。实名制校园社交平台，注册审核、动态发布、点赞评论、管理后台全流程，聊聊安全设计。', E'# 校园圈子 Campus Circle：一次 PHP + MySQL 全栈实战\n\n这是 Web 开发课程的大作业：一个面向高校学生的实名社交平台。从数据库设计到部署上线，我第一次走完了一个 Web 应用的完整生命周期。\n\n## 功能全景\n\n- **实名注册 + 管理员审核**：学号认证，未审核、已通过、停用三种状态边界清晰\n- **动态发布**：文字 + 图片上传，时间线展示\n- **社交互动**：点赞、评论、个人主页\n- **管理后台**：用户审核、内容管理、数据统计\n\n## 数据模型\n\n五张核心表撑起整个业务：\n\n| 表 | 职责 |\n| --- | --- |\n| users | 登录账号与密码哈希 |\n| students | 实名信息与审核状态 |\n| posts | 动态内容与图片 |\n| comments | 评论及层级关系 |\n| likes | 点赞的唯一约束 |\n\n## 安全是这门课的真正考点\n\n课程项目最容易被忽略、但老师真正想看的是安全：\n\n- **密码哈希**：password_hash / password_verify，明文想都别想\n- **CSRF 令牌**：所有写操作的表单都带一次性令牌\n- **输出转义**：动态内容一律 htmlspecialchars，杜绝 XSS\n- **上传校验**：MIME 检测 + 扩展名白名单 + 重命名存储\n\n## 写在最后\n\nphpStudy 一把梭的部署方式确实朴素，但它让我明白：**框架会变，请求-响应-数据库这条主线不会变**。项目源码在 GitHub 的 campus 仓库。', ARRAY['PHP','MySQL','Web开发','课程设计'], 'blue', 'published', now() - interval '12 days'),
('lky-seed', '卢柯宇', 'iGEM Wiki 插件：一套可复用的玻璃界面组件', 'igem-wiki-plugin-design', '以 HTML、CSS、JS 为基础的 Wiki 页面可复用插件。为竞赛团队做多页面静态站点时，如何把交互能力拆成可复用模块。', E'# iGEM Wiki 插件：一套可复用的玻璃界面组件\n\niGEM 竞赛要求团队用 Wiki 展示整个项目。页面多、证据密度高、评审时间有限——这套可复用插件就是为这个场景做的。\n\n## 为什么不做成单页\n\n竞赛 Wiki 有几十个页面：实验设计、结果、建模、Human Practices……单页应用在这里反而是负担。我选择**静态优先架构**：\n\n1. 每个页面是独立 HTML，部署到任何静态托管都能跑\n2. 共享一套设计系统：导航、卡片、排版全部统一\n3. 交互能力拆成独立插件，页面按需引入\n\n## 插件清单\n\n- **命令面板**：Ctrl K 唤起，全站内容秒搜\n- **悬浮 Dock**：移动端的核心导航\n- **证据筛选器**：实验数据按标签过滤\n- **术语提示**：专业词汇悬停出解释\n- **滚动叙事**：长页面按章节渐显\n\n## 复用的本质\n\n> 组件化不是把代码切开，而是把“变化”和“不变”分开。\n\n配色、字体、间距是“不变”的设计令牌；每个页面的内容结构是“变化”的部分。插件只依赖令牌，不依赖页面——这是它真正能搬去别的项目用的原因。\n\n代码在 GitHub 的 wiki-plugin 仓库，欢迎参考。', ARRAY['HTML','CSS','JavaScript','前端'], 'mint', 'published', now() - interval '6 days'),
('lky-seed', '卢柯宇', '从作品集到博客：为什么我要开始写作', 'from-portfolio-to-blog', '做完五个项目之后，我决定开一个技术博客。聊聊作品和文字的关系，以及这个博客的技术栈。', E'# 从作品集到博客：为什么我要开始写作\n\n我的个人主页迭代了好几版，项目也越攒越多。但我逐渐发现一个问题：**作品集只能告诉你我做了什么，没法告诉你我是怎么想的。**\n\n## 作品是结果，文字是过程\n\n一个项目卡片可以写“实现了智能计费模型”，但写不下这些：\n\n- 为什么第一版计费逻辑是错的\n- 调试到凌晨两点发现的是个什么 bug\n- 如果重做一遍，我会换掉哪个技术选型\n\n这些“过程性知识”才是真正会复利的部分。写下来，既是给未来的自己，也是给可能遇到同样问题的人。\n\n## 这个博客的技术栈\n\n既然要写，载体也得是自己做的：\n\n| 层 | 方案 |\n| --- | --- |\n| 前端 | React + Vite |\n| 文章数据 | 云端数据库（PostgreSQL） |\n| 图片附件 | 云端对象存储 |\n| 登录认证 | 邮箱验证码 / 密码登录 |\n| 写作格式 | Markdown |\n\n登录后我就可以在线写文、上传封面、一键发布。对访客来说不用登录，打开就能读。\n\n## 更新计划\n\n每个月至少两篇：一篇项目或技术复盘，一篇自由选题。立字为据。\n\n如果你也在学计算机、也在折腾自己的小项目，关于页面有我的联系方式，来聊聊。', ARRAY['随笔','写作','成长'], 'coral', 'published', now() - interval '2 days');
